entries[245610] = { ["name"] = "Leerenlichtwoge", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Im ständigen Wechsel zwischen strahlendem Licht und verschlingender Leere, tanzt er in perfektem Gleichgewicht durch die Wolken.\"\nPromotion" }
entries[245611] = { ["name"] = "Zuckende Kiste des Gipfels", ["text"] = "Wird beim Aufheben gebunden\n\"Wöchentliche Truhe mit Materialien zur Aufwertung von Ausrüstung, Gold, Haustieren und vielem mehr.Die ersten beiden wöchentlichen Truhen, die Ihr Euch jede Woche verdient, enthalten einen Ausrüstungsgegenstand des Veteranen. Die ersten vier wöchentlichen Truhen, die Ihr Euch jede Woche verdient, enthalten einen restaurierten Kastenschlüssel.\"\n<Zum Öffnen rechtsklicken>" }
