entries[245693] = { ["name"] = "K'areshibänder-Vorrat", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Umhangvorlagen des K'areshibänder-Vorrats.\nBenötigt Ruhmrang 14 beim Bund von K'aresh." }
entries[245694] = { ["name"] = "Zügel der ebenweißen Wutmähne", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Eure ebenweiße Wutmähne oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Laut den Legenden der Raptari wurde der angehende König Dazar während seines ersten Aufstiegs über die Hänge Zandalars von schimmernden Schuppen aus Elfenbein und rot leuchtenden Augen durch die Dunkelheit geführt.\"\nVerkäufer:\nChurbro\nZone:\nHafen von Boralus\nKosten:\n5000\n\nVerkäufer:\nChurbro\nZone:\nZuldazar\nKosten:\n5000" }
entries[245695] = { ["name"] = "Zügel des mondbeleuchteten Nachtsäblers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren mondbeleuchteten Nachtsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das weiße Schimmern ihres silbernen Fells, der strahlend blaue Blick in ihren monderleuchteten Augen. Oh, wie die Monde auf diese Kreaturen herablächeln.\" - Mutter Kalo'thera, Hohepriesterin von Elune, Ein Segen in Hajiri\nVerkäufer:\nChurbro\nZone:\nHafen von Boralus\nKosten:\n5.000\n\nVerkäufer:\nChurbro\nZone:\nZuldazar\nKosten:\n5.000" }
