entries[246067] = { ["name"] = "Perlkrolusk", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nPerlkrolusk beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Kroluske wurden als invasive Spezies nach K'aresh gebracht und fanden dort Nutzen beim Transport von Lasten.\"\nBeute:\nUrmag\nZone:\nK'aresh" }
entries[246071] = { ["name"] = "Arkannadel des Manaschneiders", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n5,414 - 7,325 Schaden Geschwindigkeit 3.60\n(1,769 Schaden pro Sekunde)\n+20.901 Intelligenz\n+32.645 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.467.\n+ 768 Vielseitigkeit\nHaltbarkeit 120 / 120\nAnlegen: Eure Zauber haben eine Chance, Euch einen Stapel 'Ätherplatte', bis zu einem Maximum von 5 Stapeln.\n\nWenn Ihr das nächste Mal direkten, zielgerichteten Schaden erleidet, wird eine 'Ätherplatte' verbraucht und dieser Schaden um 50% verringert, bis zu einem Maximum von 160756 .\nVerkaufspreis:" }
entries[246072] = { ["name"] = "Aufwendige Immerkalte Perle", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Instabile Magie '.\n\nInstabile Magie\nEure kritischen Treffer haben eine Chance, einen Magieschub auszulösen und Gegnern innerhalb von 6 Metern um Euer Ziel [(342% Angriffs-/Zaubermacht)] Arkanschaden zuzufügen.\n\n' Narans Immerscheibe ' erzielt jetzt immer einen kritischen Treffer bei mit ' Teufelsberührt ' belegten Gegnern.\n80 ( 80)" }
entries[246073] = { ["name"] = "Aufwendiger Zorn der Gezeiten", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Berührung der Bosheit '.\n\nBerührung der Bosheit\nEure Schaden verursachenden Zauber und Fähigkeiten sowie die Eurer Diener belegen Gegner regelmäßig mit ' Teufelsberührt '. Der durch ' Verdrehter Kreuzzug ' beschworene höllische Schreckenslord trifft mit ' Teufelsberührt ' belegte Gegner immer kritisch.\n\nTeufelsberührt\nAlle 4 Sek. explodiert das Ziel und fügt Gegnern in der Nähe 3% des in den letzten 4 Sek. erlittenen Schadens zu.\n\nFügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n80 ( 80)" }
entries[246074] = { ["name"] = "Aufwendiger Gesplitterter Komet", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Schrecken aus der Tiefe '.\n\nSchrecken aus der Tiefe\nEure Fähigkeiten ziehen regelmäßig ein Ungetüm aus der Tiefe an, das Euren Gegner sucht und [(440% Angriffs-/Zaubermacht)] Naturschaden verursacht, der gleichmäßig auf alle Gegner in der Nähe des Ziels aufgeteilt wird.\n\nWenn der ' Schrecken aus der Tiefe ' einen Gegner mit ' Teufelsberührt ' trifft, verursacht er ' Tiefensogschmettern ' und fügt allen Gegnern in der Nähe [(440% Angriffs-/Zaubermacht)] Naturschaden zu.\n80 ( 80)" }
entries[246075] = { ["name"] = "Aufwendiger Gelmoggs geborstener Schädel", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Seelenstärke des Hochbergs '.\n\nSeelenstärke des Hochbergs\nAlle 12 Sek. sammelt Ihr 3% von sämtlichem erlittenen Schaden als ' Seelenstärke ' an. Nach 8 Sek. wird ' Seelenstärke ' zu einer Schutzbarriere, die 4 Sek. lang Schaden in der angesammelten Höhe absorbiert.\n80 ( 80)" }
entries[246076] = { ["name"] = "Aufwendiges Ettinknochenfragment", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Seelen des Krächzens '.\n\nSeelen des Krächzens\nEure Zauber und Fähigkeiten haben eine Chance, einen Schwarm Geisteradler zu beschwören, die auf Gegner in der Nähe herabstürzen und bei Aufprall explodieren. Explosionen heilen Verbündete und fügen Gegnern innerhalb von 5 Metern [[2 * (368% Angriffs-/Zaubermacht)]][[(368% Angriffs-/Zaubermacht)]] Naturschaden zu.\n80 ( 80)" }
entries[246077] = { ["name"] = "Aufwendiger Schimmernder Eisendorn", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Arkane Aegis '.\n\nArkane Aegis\nIhr kanalisiert bei Rückwärtsbewegung ' Arkane Aegis ', absorbiert bis zu [(2100% Angriffs-/Zaubermacht)] Schaden und verringert Eure Bewegungsgeschwindigkeit um 80%. Wenn Ihr ' Arkane Aegis ' nicht kanalisiert, regeneriert sie sich um 5% pro Sekunde. Wird die ' Arkane Aegis ' zerschlagen, ist sie 30 Sek. lang unbenutzbar.\n80 ( 80)" }
entries[246078] = { ["name"] = "Aufwendige Xakals Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Gewährt 2 zusätzliche Ränge von ' Temporalgegenschlag '.\n\nTemporalgegenschlag\nWenn Ihr Schaden absorbiert, fügt Ihr dem Angreifer [(31% Angriffs-/Zaubermacht)] Arkanschaden zu und verringert sein Angriffstempo 3 Sek. lang um 20%.\n80 ( 80)" }
