entries[246159] = { ["name"] = "Verlagerter Verschlinger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Fresser wurde versehentlich transportiert, als die Mittler Tazavesh verschoben haben, und hat eine neue Welt voller mächtiger Energiequellen gefunden, insbesondere Animaleuchtfeuer... und Reiter.\"\nBeute:\nVerschlingerschwärme\nZone:\nTazavesh" }
